package tallydb

import (
	"encoding/binary"
	"fmt"
)

// genesisLedgerName is the placeholder name in the genesis patch.
const genesisLedgerName = "FIRSTLEDG"

// genesisValidations verifies the file structure before applying the patch.
// Key pages must have expected seq and type values.
func genesisValidate(data []byte) error {
	type check struct{ page int; seq uint32; otype uint16 }
	checks := []check{{24, 20, 0x000B}, {33, 29, 0x000B}, {368, 205, 0x000B}}
	for _, c := range checks {
		if len(data) < (c.page+1)*PageSize { return fmt.Errorf("file too small") }
		seq := binary.LittleEndian.Uint32(data[c.page*PageSize+4:])
		otyp := binary.LittleEndian.Uint16(data[c.page*PageSize+16:])
		if seq != c.seq || otyp != c.otype {
			return fmt.Errorf("page %d: expected seq=%d type=0x%04x, got seq=%d type=0x%04x", c.page, c.seq, c.otype, seq, otyp)
		}
	}
	return nil
}

